var n=`1037-mie-goreng`;var t=`world-1037`;var s=`ID`;var a=`southeast-asia`;var r=4;var o=25;var g={en:`Mie Goreng`,ua:`Мі горенг`};var d={en:`Mie Goreng is a dish from Indonesia prepared with egg noodles, garlic, shallot, chicken breast. This is a home-scale version with measured ingredients in the individual steps where they are used.`,ua:`Мі горенг, страва кухні країни Індонезія, яку готують із таких продуктів: яєчна локшина, часник, цибуля шалот, куряча грудка. Кількості в домашньому рецепті прив’язані до окремих етапів приготування.`};var l=[{en:`Cook the listed ingredients in simmering water for about 6 minutes until tender; drain well if necessary.`,ua:`Варіть зазначені складники у воді приблизно 6 хвилин до м’якості; за потреби добре злийте воду.`,t:[`boiling`],m:6,i:[[`egg-noodles`,460,`g`],[`water`,1100,`ml`]]},{en:`Chop the vegetables as needed. Sauté the listed ingredients over medium heat, stirring, for about 8 minutes until softened and aromatic.`,ua:`Наріжте овочі за потреби. Пасеруйте зазначені складники на середньому вогні, помішуючи, приблизно 8 хвилин до м’якості й аромату.`,t:[`chopping`,`sauteing`],m:8,i:[[`garlic`,4,`clove`],[`shallot`,120,`g`],[`canola-oil`,45,`ml`],[`chicken-breast`,400,`g`]]},{en:`Chop the vegetables as needed. Sauté the listed ingredients over medium heat, stirring, for about 8 minutes until softened and aromatic.`,ua:`Наріжте овочі за потреби. Пасеруйте зазначені складники на середньому вогні, помішуючи, приблизно 8 хвилин до м’якості й аромату.`,t:[`chopping`,`sauteing`],m:8,i:[[`white-cabbage`,230,`g`],[`carrot`,170,`g`],[`sweet-soy-sauce-kecap-manis`,60,`ml`],[`light-soy-sauce`,25,`ml`]]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:3,i:[[`green-onion`,30,`g`],[`crushed-red-pepper`,3,`g`]]}];var h={slug:n,id:t,country:`ID`,region:a,servings:4,minutes:25,title:g,text:d,steps:l};export{s as country,h as default,t as id,o as minutes,a as region,r as servings,n as slug,l as steps,d as text,g as title};